DROP POLICY quality_read ON public.quality_items;
CREATE POLICY quality_read ON public.quality_items FOR SELECT TO authenticated USING(public.is_director(auth.uid()) OR (public.is_ops(auth.uid()) AND kind IN ('complaints','improvements','consent','review_request','referral_request','recovery_request','standards')) OR (assigned_user_id=auth.uid() AND kind IN ('complaints','education','improvements')) OR (owner_id=auth.uid() AND kind IN ('consent','invitation','response','review_request','referral_request')) OR (kind='education' AND state='PUBLISHED' AND (payload->>'validUntil')::timestamptz>=now()) OR (kind='surveys' AND state='PUBLISHED' AND public.quality_has_invitation(id)));
CREATE FUNCTION public.quality_family_cases() RETURNS SETOF public.quality_items LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT id,kind,(payload - 'reviewEvidence' - 'reviewedBy' - 'professionalReviewed' - 'plan' - 'evidence' - 'events' - 'assignedTo') || jsonb_build_object('professionalReviewed',false,'plan','','evidence','','events','[]'::jsonb,'assignedTo',''),version,state,owner_id,NULL::uuid,created_by,created_at,updated_at FROM public.quality_items WHERE kind='complaints' AND owner_id=auth.uid() AND public.has_any_role(auth.uid(),ARRAY['cliente']::public.app_role[]);
$$;
REVOKE ALL ON FUNCTION public.quality_family_cases() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.quality_family_cases() TO authenticated;
CREATE FUNCTION public.quality_timeline(_entity uuid) RETURNS TABLE(actor_id uuid,action text,reason text,old_version integer,new_version integer,at timestamptz) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT actor_id,action,reason,old_version,new_version,at FROM public.quality_audit WHERE entity_id=_entity ORDER BY at; $$;
REVOKE ALL ON FUNCTION public.quality_timeline(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.quality_timeline(uuid) TO authenticated;